validator:
function validate([graph]) {
  const n = graph.length;
  if (n < 2 || n > 100) return 'The party needs 2 to 100 people.';
  if (graph.some(row => row.length !== n)) return 'graph must be a square n by n matrix.';
  if (graph.some(row => row.some(v => v !== 0 && v !== 1))) return 'Every entry of graph is 0 or 1.';
  if (graph.some((row, i) => row[i] !== 1)) return 'Everyone knows themselves: graph[i][i] must be 1.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [graph] = input;
  const n = graph.length;
  // The solution sees only n; the matrix is reachable through the global knows(a, b).
  globalThis.knows = (a, b) => {
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) throw new Error('knows(a, b) takes two labels from 0 to n - 1.');
    return graph[a][b] === 1;
  };
  const result = solve(n);
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (!Number.isInteger(result)) throw new Error("Return a person's label or -1.");
  return result;
}

reference:
function findCelebrity(n) {
  let candidate = 0;
  for (let i = 1; i < n; i++) {
    if (knows(candidate, i)) {
      candidate = i;
    }
  }

  for (let i = 0; i < n; i++) {
    if (i === candidate) {
      continue;
    }
    if (knows(candidate, i) || !knows(i, candidate)) {
      return -1;
    }
  }
  return candidate;
}

brute:
function findCelebrity(n) {
  // Test every person against the definition directly.
  for (let person = 0; person < n; person++) {
    let ok = true;
    for (let other = 0; other < n && ok; other++) {
      if (other !== person && (!knows(other, person) || knows(person, other))) ok = false;
    }
    if (ok) return person;
  }
  return -1;
}

