function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 100 : 2 + pick(6);
  const density = rand();
  const graph = Array.from({ length: n }, (_, a) => Array.from({ length: n }, (_, b) => (a === b || rand() < density ? 1 : 0)));
  const mode = pick(4);
  if (mode >= 1) {
    // Plant a celebrity, and in mode 2 or 3 spoil it with one missing or one extra link.
    const celebrity = pick(n);
    for (let p = 0; p < n; p++) if (p !== celebrity) { graph[p][celebrity] = 1; graph[celebrity][p] = 0; }
    let other = pick(n - 1);
    if (other >= celebrity) other++;
    if (mode === 2) graph[other][celebrity] = 0;
    if (mode === 3) graph[celebrity][other] = 1;
  }
  return [graph];
}
